import{_ as t,o as a,c as s,ag as n}from"./chunks/framework.Pp2klvcf.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/architecture.md","filePath":"en/guide/architecture.md","lastUpdated":1788681727000}'),i={name:"en/guide/architecture.md"};function r(o,e,c,p,l,d){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Fast-Vue3 maintains two parallel branches. <code>polyrepo</code> is a single Vue application with build-time UI selection. <code>main</code> is a pnpm/Turbo workspace with independent admin and portal applications.</p><p>Application logic follows Views → Store → API → HTTP. config/ui.ts provides a shared UI registry; Vite aliases select setup, theme provider, login form and showcase modules. The all mode composes seven showcases and uses Element Plus for login.</p><p>The application owns --fv-* design tokens and responsive layout. Ant Design/Naive/iDux use theme providers; Element Plus/Arco/TDesign use their theme selectors; DevUI uses its theme service. This keeps application styling independent of library resets.</p><p>Run pnpm check and build the selected UI mode. Also check desktop/mobile, light/dark and keyboard interaction. Mock only runs in development at /api/user/*.</p><p>apps/ contains independently runnable admin and portal templates. packages/ contains request, stores, preferences, styles, layout, access, locales and shared contracts. internal/ contains Vite, TypeScript and lint tooling. scripts/ contains vsh and turbo-run.</p><p>workspace:* links local packages; catalog: centralizes dependency versions. Turbo dev/build depend on upstream ^build. The Vite config package loads dist/index.mjs, so tool changes require stub/build.</p><p>Use pnpm create-app to generate an admin or site app and add root dev/build scripts. Main’s request API returns an Axios instance from createHttpClient; createRequest unwraps result. Do not assume it implements polyrepo’s ApiError/204 handling.</p>',8)])])}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
